INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Detachable-Gerät immer ein vollwertiger PC?', 2, '[{"text": "Nein", "correct": true, "because": "Oft eingeschränkte Leistung"}, {"text": "Ja", "correct": false, "because": "Nicht immer desktopstark"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature macht ein Detachable besonders?', 3, '[{"text": "Abnehmbare Tastatur", "correct": true, "because": "Flexibilität zwischen Tablet und Laptop"}, {"text": "Hohe Taktfrequenz", "correct": false, "because": "Nicht primär"}, {"text": "Großer Cache", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein solches Gerät?', 5, '[{"text": "Mobilität", "correct": true, "because": "Leicht und tragbar"}, {"text": "Dualer Einsatz", "correct": true, "because": "Tablet und Laptop"}, {"text": "Maximale Leistung", "correct": false, "because": "Eher kompromissbehaftet"}, {"text": "Großer Speicher", "correct": false, "because": "Oft begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Detachables sind leicht. b) Sie ersetzen Desktop-PCs komplett.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Leistung oft geringer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Auswahl eines solchen Geräts?', 4, '[{"text": "Akkulaufzeit", "correct": false, "because": "Wichtig für Mobilität"}, {"text": "Anschlüsse", "correct": false, "because": "Beeinflusst Nutzung"}, {"text": "Farbauswahl", "correct": true, "because": "Rein ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Detachable immer Touchscreen hat?', 2, '[{"text": "Ja", "correct": true, "because": "Tabletfunktion erfordert es"}, {"text": "Nein", "correct": false, "because": "Selten ohne Touch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Betriebssystem passt typischerweise zu Detachables?', 3, '[{"text": "Windows", "correct": true, "because": "Optimiert für 2-in-1"}, {"text": "Linux", "correct": false, "because": "Weniger Touch-fokussiert"}, {"text": "DOS", "correct": false, "because": "Veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Szenarien eignen sich für ein Detachable?', 5, '[{"text": "Mobile Präsentationen", "correct": true, "because": "Tablet-Modus praktisch"}, {"text": "Pendeln", "correct": true, "because": "Leicht und kompakt"}, {"text": "High-End-Gaming", "correct": false, "because": "Leistung begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Detachables sind flexibel. b) Sie haben immer starke GPUs. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "GPU oft integriert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Detachable?', 4, '[{"text": "Touchscreen", "correct": false, "because": "Kernfunktion"}, {"text": "Abnehmbare Tastatur", "correct": false, "because": "Definiert das Gerät"}, {"text": "Externe Festplatte", "correct": true, "because": "Interner Speicher reicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Detachables nur für Privatnutzung?', 2, '[{"text": "Nein", "correct": true, "because": "Auch geschäftlich nützlich"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind bei einem Detachable entscheidend?', 4, '[{"text": "Akku", "correct": true, "because": "Mobile Nutzung"}, {"text": "Prozessor", "correct": true, "because": "Leistung wichtig"}, {"text": "Dedizierte GPU", "correct": false, "because": "Oft integriert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Detachables schwer sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Entworfen für Mobilität"}, {"text": "Ja", "correct": false, "because": "Leichtbauweise üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Detachable?', 3, '[{"text": "Gewicht", "correct": true, "because": "Mobilität entscheidend"}, {"text": "Maximale RAM-Größe", "correct": false, "because": "Sekundär"}, {"text": "Optik", "correct": false, "because": "Funktion zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Detachables sind 2-in-1-Geräte. b) Sie haben immer Desktop-Leistung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Leistung oft limitiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Features machen ein Detachable praktisch?', 5, '[{"text": "Touchscreen", "correct": true, "because": "Tablet-Modus"}, {"text": "Leichtbauweise", "correct": true, "because": "Einfacher Transport"}, {"text": "Viele USB-Ports", "correct": false, "because": "Oft begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Detachable unwichtig?', 3, '[{"text": "Bildschirmgröße", "correct": false, "because": "Beeinflusst Nutzung"}, {"text": "Akkulaufzeit", "correct": false, "because": "Kernmerkmal"}, {"text": "Lautsprecherlautstärke", "correct": true, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Detachables auch für Entwickler geeignet?', 3, '[{"text": "Ja", "correct": true, "because": "Mit passender Leistung"}, {"text": "Nein", "correct": false, "because": "Nicht grundsätzlich ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Detachable immer teuer ist?', 2, '[{"text": "Nein", "correct": true, "because": "Preisspanne variiert"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig teuer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Detachable?', 4, '[{"text": "Flexibilität im Einsatz", "correct": true, "because": "Tablet und Laptop"}, {"text": "Maximale Gaming-Leistung", "correct": false, "because": "Nicht Hauptfokus"}, {"text": "Hoher Stromverbrauch", "correct": false, "because": "Effizienz zählt"}]');
